#!/bin/sh
# gate-diff-size.sh — count non-lockfile changed lines in a unified diff.
#
# Shepherd uses this both from validate.sh (R0 path blocklist + size cap) and
# from the SH-009 gates workflow (gate.diff-size re-run on every PR update).
# Having one script owns the LOCKFILE_RE prevents the two paths from drifting.
#
# Lockfile paths exempt from the count: they're regenerated by the ecosystem's
# package manager, not by the agent, and legitimately grow large.
#
# Usage:
#   gate-diff-size.sh <diff-path>                   # non-lockfile count (default)
#   gate-diff-size.sh <diff-path> --non-lockfile    # same, explicit
#   gate-diff-size.sh <diff-path> --lockfile        # lockfile-only count
#
# Exit codes:
#   0  count printed to stdout
#   3  usage / IO error

set -eu

if [ $# -lt 1 ] || [ $# -gt 2 ]; then
  echo "usage: $0 <diff-path> [--non-lockfile|--lockfile]" >&2
  exit 3
fi
DIFF=$1
mode=${2:---non-lockfile}

if [ ! -f "$DIFF" ]; then
  echo "no such file: $DIFF" >&2
  exit 3
fi

# Keep this regex in sync with validate.sh's LOCKFILE_RE.
LOCKFILE_RE='^(package-lock[.]json|yarn[.]lock|pnpm-lock[.]yaml|poetry[.]lock|Pipfile[.]lock|go[.]sum|Cargo[.]lock)$'

case "$mode" in
  --non-lockfile)
    awk -v re="$LOCKFILE_RE" '
      /^diff --git a\// {
        path = $0
        sub(/^diff --git a\//, "", path)
        sub(/ b\/.*$/, "", path)
        in_lock = (path ~ re) ? 1 : 0
        next
      }
      /^--- / || /^\+\+\+ / { next }
      !in_lock && /^[+-]/    { n++ }
      END { print n+0 }
    ' "$DIFF"
    ;;
  --lockfile)
    awk -v re="$LOCKFILE_RE" '
      /^diff --git a\// {
        path = $0
        sub(/^diff --git a\//, "", path)
        sub(/ b\/.*$/, "", path)
        in_lock = (path ~ re) ? 1 : 0
        next
      }
      /^--- / || /^\+\+\+ / { next }
      in_lock && /^[+-]/     { n++ }
      END { print n+0 }
    ' "$DIFF"
    ;;
  *)
    echo "unknown mode: $mode" >&2
    exit 3
    ;;
esac
